CREATE TABLE catalog_meta (id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL DEFAULT 0, authority_ready INTEGER NOT NULL DEFAULT 0 CHECK(authority_ready IN (0,1)));
INSERT INTO catalog_meta(id) VALUES(1);
CREATE TABLE catalog_groups (id TEXT PRIMARY KEY, version INTEGER NOT NULL, name TEXT NOT NULL, content_json TEXT NOT NULL CHECK(json_valid(content_json)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE catalog_entries (id TEXT PRIMARY KEY, version INTEGER NOT NULL, record_kind TEXT NOT NULL CHECK(record_kind IN ('resource','position')), group_id TEXT REFERENCES catalog_groups(id), owner_id TEXT, name TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN (0,1)), content_json TEXT NOT NULL CHECK(json_valid(content_json)), published_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX catalog_entries_listing ON catalog_entries(record_kind,deleted,updated_at,id);
CREATE TABLE catalog_versions (target_type TEXT NOT NULL CHECK(target_type IN ('entry','group')), target_id TEXT NOT NULL, version INTEGER NOT NULL, content_json TEXT NOT NULL CHECK(json_valid(content_json)), actor_id TEXT, actor_name TEXT NOT NULL, issue_id TEXT, created_at TEXT NOT NULL, PRIMARY KEY(target_type,target_id,version));
CREATE TRIGGER catalog_versions_immutable_update BEFORE UPDATE ON catalog_versions BEGIN SELECT RAISE(ABORT,'catalog versions are immutable'); END;
CREATE TRIGGER catalog_versions_immutable_delete BEFORE DELETE ON catalog_versions BEGIN SELECT RAISE(ABORT,'catalog versions are immutable'); END;
CREATE TABLE catalog_issues (id TEXT PRIMARY KEY, version INTEGER NOT NULL DEFAULT 1, target_type TEXT NOT NULL CHECK(target_type IN ('entry','group')), target_id TEXT NOT NULL, base_version INTEGER NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, proposal_json TEXT CHECK(proposal_json IS NULL OR json_valid(proposal_json)), author_id TEXT NOT NULL, author_name TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','merged','closed')), result TEXT NOT NULL DEFAULT '', handled_by TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX catalog_issues_target ON catalog_issues(target_type,target_id,created_at,id);
CREATE TABLE catalog_comments (id TEXT PRIMARY KEY, issue_id TEXT NOT NULL REFERENCES catalog_issues(id), author_id TEXT NOT NULL, author_name TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE catalog_grants (id TEXT PRIMARY KEY, version INTEGER NOT NULL DEFAULT 1, entry_id TEXT NOT NULL REFERENCES catalog_entries(id), recipient_name TEXT NOT NULL, recipient_archive_id TEXT, receiver_id TEXT NOT NULL, receiver_name TEXT NOT NULL, issued_by TEXT NOT NULL, issuer_name TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, note TEXT NOT NULL DEFAULT '', state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','received','cancelled')), revoked_at TEXT, received_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX catalog_grants_receiver ON catalog_grants(receiver_id,created_at,id);
CREATE TABLE catalog_grant_events (id TEXT PRIMARY KEY, grant_id TEXT NOT NULL REFERENCES catalog_grants(id), actor_id TEXT NOT NULL, action TEXT NOT NULL, result TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE catalog_files (id TEXT PRIMARY KEY, entry_id TEXT REFERENCES catalog_entries(id), author_id TEXT NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, bytes INTEGER NOT NULL CHECK(bytes>0 AND bytes<=10485760), sha256 TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, state TEXT NOT NULL CHECK(state IN ('pending','ready')), created_at TEXT NOT NULL);
CREATE TABLE catalog_requests (actor_id TEXT NOT NULL, request_id TEXT NOT NULL, fingerprint TEXT NOT NULL, result_json TEXT NOT NULL CHECK(json_valid(result_json)), created_at TEXT NOT NULL, PRIMARY KEY(actor_id,request_id));
CREATE TABLE catalog_imports (id TEXT PRIMARY KEY, source_database_id TEXT NOT NULL, digest TEXT NOT NULL, entry_count INTEGER NOT NULL, history_count INTEGER NOT NULL, imported_at TEXT NOT NULL);
CREATE TABLE catalog_source_history (id TEXT PRIMARY KEY, source_json TEXT NOT NULL CHECK(json_valid(source_json)), imported_at TEXT NOT NULL);
